import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { logout } from '../store/slices/authSlice';

const Navbar = ({ userType }) => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.auth);

  const handleLogout = () => {
    dispatch(logout());
    navigate('/login');
  };

  const artistLinks = [
    { to: '/artist/gallery', label: 'Gallery' },
    { to: '/artist/artworks', label: 'Artworks' },
    { to: '/artist/artists', label: 'Artists' },
    { to: '/artist/inbox', label: 'Inbox' },
  ];

  const collectorLinks = [
    { to: '/collector/gallery', label: 'Gallery' },
    { to: '/collector/artists', label: 'Artists' },
    { to: '/collector/about', label: 'About' },
    { to: '/collector/inbox', label: 'Inbox' },
  ];

  const links = userType === 'artist' ? artistLinks : collectorLinks;

  return (
    <nav className="bg-white shadow-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          <div className="flex">
            <Link to="/" className="flex items-center">
              <span className="text-2xl font-bold text-coral">ArtGallery</span>
            </Link>
          </div>

          <div className="flex items-center space-x-4">
            {links.map((link) => (
              <Link
                key={link.to}
                to={link.to}
                className="text-brown hover:text-coral px-3 py-2 rounded-md text-sm font-medium"
              >
                {link.label}
              </Link>
            ))}

            <div className="relative ml-3">
              <div className="flex items-center space-x-4">
                <Link
                  to={userType === 'artist' ? '/artist/profile' : '/collector/profile'}
                  className="text-brown hover:text-coral"
                >
                  <img
                    src={user.profileImage || 'https://via.placeholder.com/32'}
                    alt="Profile"
                    className="h-8 w-8 rounded-full"
                  />
                </Link>
                <button
                  onClick={handleLogout}
                  className="text-brown hover:text-coral"
                >
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    className="h-6 w-6"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"
                    />
                  </svg>
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
